INSERT INTO contorno_grupos (nombre) VALUES ('Cambio de acompañamiento') ON CONFLICT(nombre) DO NOTHING;
INSERT INTO contorno_variantes (grupo_id,nombre,suplemento_centavos,extra_centavos,activo) SELECT id,'Mantener acompañamiento',0,0,1 FROM contorno_grupos WHERE nombre='Cambio de acompañamiento' ON CONFLICT(grupo_id,nombre) DO UPDATE SET suplemento_centavos=0,activo=1;
INSERT INTO contorno_variantes (grupo_id,nombre,suplemento_centavos,extra_centavos,activo) SELECT id,'Cambiar por papas fritas',1000,0,1 FROM contorno_grupos WHERE nombre='Cambio de acompañamiento' ON CONFLICT(grupo_id,nombre) DO UPDATE SET suplemento_centavos=1000,activo=1;
INSERT INTO plato_slots (producto_id,posicion,nombre,permite_extra) SELECT id,1,'Acompañamiento',0 FROM productos WHERE codigo='menu-real:platos-completos:bandeja-paisa' ON CONFLICT(producto_id,posicion) DO UPDATE SET nombre='Acompañamiento',permite_extra=0;
INSERT INTO plato_slot_grupos (slot_id,grupo_id) SELECT ps.id,cg.id FROM plato_slots ps JOIN productos p ON p.id=ps.producto_id CROSS JOIN contorno_grupos cg WHERE p.codigo='menu-real:platos-completos:bandeja-paisa' AND ps.posicion=1 AND cg.nombre='Cambio de acompañamiento' ON CONFLICT(slot_id,grupo_id) DO NOTHING;
